class isadActions extends sfActions
{
  public function executeIndex()
  {
    return $this->forward('isad', 'list');
  }

  public function executeList()
  {
    $this->isads = IsadPeer::doSelect(new Criteria());
  }

  public function executeShow()
  {
    $this->isad = IsadPeer::retrieveByPk($this->getRequestParameter('isad_id'));
    $this->forward404Unless($this->isad);
  }

  public function executeCreate()
  {
    $this->isad = new Isad();

    $this->setTemplate('edit');
  }

  public function executeEdit()
  {
  	/*********************************************************************************************************/
  	$c = new Criteria();
  	$c->add(IsadPeer::UNIDADDOCUMENTAL_ID,$this->getRequestParameter('unidaddocumental_id'));
  	$campo_isad = IsadPeer::doSelectOne($c);
  	/*********************************************************************************************************/
  	if($campo_isad != null){
		$this->isad = $campo_isad;
	}else{
	    $this->isad = new Isad();	
	}
    //$this->isad = IsadPeer::retrieveByPk($this->getRequestParameter('isad_id'));
    $this->forward404Unless($this->isad);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('isad_id'))
    {
      $isad = new Isad();
    }
    else
    {
      $isad = IsadPeer::retrieveByPk($this->getRequestParameter('isad_id'));
      $this->forward404Unless($isad);
    }

    //$isad->setIsadId($this->getRequestParameter('isad_id'));
    $isad->setUnidaddocumentalId($this->getRequestParameter('unidaddocumental_id'));
    $isad->setNiveldescripcionId($this->getRequestParameter('niveldescripcion_id'));
    $isad->setCodigoReferencia($this->getRequestParameter('codigo_referencia'));
    $isad->setTitulo($this->getRequestParameter('titulo'));
    if ($this->getRequestParameter('fecha_acumulacion'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_acumulacion'), $this->getUser()->getCulture());
      $isad->setFechaAcumulacion("$y-$m-$d");
    }
    $isad->setNombreProductor($this->getRequestParameter('nombre_productor'));
    $isad->setResenaBibliografica($this->getRequestParameter('resena_bibliografica'));
    $isad->setHistoriaArchivistica($this->getRequestParameter('historia_archivistica'));
    $isad->setFormaIngreso($this->getRequestParameter('forma_ingreso'));
    $isad->setAlcanceContenido($this->getRequestParameter('alcance_contenido'));
    $isad->setValoracionSeleccionEliminacion($this->getRequestParameter('valoracion_seleccion_eliminacion'));
    $isad->setNuevosIngresos($this->getRequestParameter('nuevos_ingresos'));
    $isad->setOrganizacion($this->getRequestParameter('organizacion'));
    $isad->setCondicionesAcceso($this->getRequestParameter('condiciones_acceso'));
    $isad->setCondicionesReproduccion($this->getRequestParameter('condiciones_reproduccion'));
    $isad->setLenguaEscrituraDocumetos($this->getRequestParameter('lengua_escritura_documetos'));
    $isad->setCaracteristicasFisicas($this->getRequestParameter('caracteristicas_fisicas'));
    $isad->setIntrumentosDescripcion($this->getRequestParameter('intrumentos_descripcion'));
    $isad->setLocalizacionOriginales($this->getRequestParameter('localizacion_originales'));
    $isad->setLocalizacionCopias($this->getRequestParameter('localizacion_copias'));
    $isad->setUnidadesDescripcionRelacionadas($this->getRequestParameter('unidades_descripcion_relacionadas'));
    $isad->setNotaDescripcion($this->getRequestParameter('nota_descripcion'));
    $isad->setNotas($this->getRequestParameter('notas'));
    $isad->setNotaArchivero($this->getRequestParameter('nota_archivero'));
    $isad->setReglasNormas($this->getRequestParameter('reglas_normas'));
    if ($this->getRequestParameter('fecha_descripciones'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_descripciones'), $this->getUser()->getCulture());
      $isad->setFechaDescripciones("$y-$m-$d");
    }else{
	  $isad->setFechaDescripciones(date("Y-m-d G:i:s"));	
	}

    $isad->save();

    return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$isad->getUnidaddocumentalId().'&localizacion='.$this->getRequestParameter('localizacion'));
  }

  public function executeDelete()
  {
    $isad = IsadPeer::retrieveByPk($this->getRequestParameter('isad_id'));

    $this->forward404Unless($isad);

    $isad->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/isad/list');
  }
}
